mapper.delete:
DELETE FROM fgc.cap_check_detail
 WHERE cap_check_id = #{capCheckId}
   AND detail_seq > #{maxDetailSeq}

mapper.sql:
WITH ranked_cap_check AS ( SELECT cc.cap_check_id, cc.contract_id, ic.contract_no, ic.agent_id, ic.organization_id, cc.payment_stage, cc.as_of_date, cc.base_premium_amount, cc.refund_12m_amount, cc.compliance_deduction_amount, cc.limit_amount, cc.included_amount, cc.remaining_amount, cc.usage_pct, cc.result_status, cc.cap_rule_set_id, ROW_NUMBER() OVER ( PARTITION BY cc.contract_id, cc.payment_stage ORDER BY cc.checked_at DESC, cc.cap_check_id DESC ) AS latest_rank FROM fgc.cap_check cc JOIN fgc.insurance_contract ic ON ic.contract_id = cc.contract_id
AND date_trunc('month', cc.as_of_date) = date_trunc('month', #{month}::date)
AND ic.insurer_id = #{insurerId}
AND ic.organization_id = #{organizationId}
AND ic.contract_no = #{contractNo}
), latest_cap_check AS ( SELECT * FROM ranked_cap_check WHERE latest_rank = 1 )

mapper.select:
SELECT result_status AS resultStatus, COUNT(*) AS count FROM latest_cap_check
AND payment_stage = #{paymentStage}
GROUP BY result_status
